#include <stdio.h>
#include <stdlib.h>

int main() {
    int n = 4;
    int *values = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        values[i] = i * 10;
    }
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += values[i];
    }
    printf("%d\n", sum);
    free(values);
    return 0;
}
